
function gmwSetCookie(b,d,c){var e=new Date();e.setTime(e.getTime()+(c*24*60*60*1000));var a=escape(encodeURIComponent(d))+((c==null)?"":"; expires="+e.toUTCString());document.cookie=b+"="+a+"; path=/"}jQuery(".gmw-nav-tab-wrapper a").click(function(){jQuery(".gmw-settings-panel").hide();jQuery(".gmw-nav-tab-active").css("background","#f7f7f7");jQuery(".gmw-nav-tab-active").removeClass("gmw-nav-tab-active");jQuery(jQuery(this).attr("href")).show();jQuery(this).addClass("gmw-nav-tab-active");gmwSetCookie("gmw_admin_tab",jQuery(this).attr("id"),1);return false});jQuery(".gmw-nav-tab-wrapper a:first").click();